'use strict';
(function(root){const slots=['weapon','armor','accessory'],names={weapon:'거신의 송곳니',armor:'거신의 심장',accessory:'거신의 수정안'},labels={weapon:'무기',armor:'방어구',accessory:'장신구'},int=(v,max=1e8)=>Math.max(0,Math.min(max,Math.floor(Number(v)||0)));
function clean(raw){if(!raw||typeof raw!=='object')return null;const out={owner:typeof raw.owner==='string'?raw.owner:'',revision:int(raw.revision),crystals:int(raw.crystals),collection:{},loadouts:{}};for(const s of slots)out.collection[s]={level:int(raw.collection?.[s]?.level,10),copies:int(raw.collection?.[s]?.copies,9999)};for(let id=0;id<12;id++){out.loadouts[id]={};for(const s of slots)out.loadouts[id][s]=raw.loadouts?.[id]?.[s]===true&&out.collection[s].level>0;}return out;}
function bonus(raw,hero){const data=clean(raw),b={attack:0,maxHP:0,armor:0};if(!data)return b;const load=data.loadouts[hero]||{};for(const slot of slots){if(!load[slot])continue;const n=data.collection[slot].level;if(slot==='weapon')b.attack+=(4+2*n)/100;if(slot==='armor'){b.maxHP+=(5+3*n)/100;b.armor+=(5+3*n)/100;}if(slot==='accessory'){b.attack+=(2+n)/100;b.maxHP+=(2+n)/100;}}return b;}
function cost(level){return level===0?90:30*(level+1);}
function project(raw,hero,slot,action){const data=clean(raw);if(!data||!slots.includes(slot))return null;const item=data.collection[slot];if(action==='craft'){item.level=1;data.crystals-=90;data.loadouts[hero][slot]=true;}else if(action==='grow'){item.level=Math.min(10,item.level+1);if(item.copies>0)item.copies--;else data.crystals-=cost(item.level-1);}else if(action==='equip')data.loadouts[hero][slot]=true;else if(action==='unequip')data.loadouts[hero][slot]=false;return data;}
const API={slots,names,labels,clean,bonus,cost,project};if(typeof module!=='undefined')module.exports=API;root.RPG_RAID_LOOT=API;})(typeof window!=='undefined'?window:globalThis);
